package org.skhuconnect.notice.dto; import org.skhuconnect.notice.entity.*; import java.time.LocalDateTime; public record NoticeResponse(Long id,String title,String content,NoticeStatus status,Long createdBy,LocalDateTime createdAt,LocalDateTime updatedAt,LocalDateTime publishedAt){public static NoticeResponse from(Notice n){return new NoticeResponse(n.getId(),n.getTitle(),n.getContent(),n.getStatus(),n.getCreatedBy().getId(),n.getCreatedAt(),n.getUpdatedAt(),n.getPublishedAt());}}